function renderIndex(){let q=normalizedName($('search').value.trim());let list=scope==='unplaced'?DATA.unplaced:scope==='all'||q?allRecords:DATA.systems.filter(s=>view==='all'||s.region===view);
 if(q)list=list.filter(s=>searchTerms(s).some(value=>value&&normalizedName(value).includes(q)));
 list=[...list].sort((a,b)=>(a.name==='Virezk'?-1:b.name==='Virezk'?1:a.name.localeCompare(b.name)));
 $('indexCount').textContent=list.length+' '+(scope==='unplaced'?'RECORDS':'RESULTS');
 $('index').innerHTML=list.length?list.map(s=>`<div class="index-row ${selected===s.id?'selected':''}" style="--row-color:${color(s)}"><span class="dot"></span><div class="row-text">${systemLink(s,s.name)}${s.nickname?`<small>${esc(s.nickname)}</small>`:''}${q?`<small class="search-match">${esc(searchObject(s,q)?.name||s.affiliation||(s.tier?'Tier '+s.tier+' · '+TIER_NAMES[s.tier]:s.centralBodyType||''))}</small>`:''}${s.tier?`<small style="color:${TIER_COLORS[s.tier]}">Tier ${s.tier} · ${TIER_NAMES[s.tier]}${s.centralBodyType==='silent-darkened'?' · Dead star':''}</small>`:''}${s.unplottedSystem?'<small>Black hole · coordinates classified</small>':''}<small>${esc(s.worlds.join(' · ')||(s.region?DATA.regions[s.region].name:s.kind==='classified'?'Coordinates classified':s.kind==='hazard'?'Kurzenzka · unplotted':'Position unspecified'))}</small></div><button class="inspect" data-inspect="${esc(s.id)}" aria-label="Inspect ${esc(s.name)}">›</button></div>`).join(''):'<div class="index-empty">No matching locations.<br>Try a name, Tier 5, Elysian Collective, ruins or magnetar.</div>';
 $('index').querySelectorAll('[data-inspect]').forEach(b=>b.onclick=()=>select(b.dataset.inspect,q?searchObject(resolveSystem(b.dataset.inspect),q)?.name||null:null,true));
}
